'use strict';
// Somente configuracao local, hashes e transacao MySQL READ ONLY.
const fs=require('node:fs'),path=require('node:path'),os=require('node:os'),crypto=require('node:crypto'),assert=require('node:assert/strict');
const root=path.resolve(__dirname,'..'),sha=b=>crypto.createHash('sha256').update(b).digest('hex');
async function main(){
 const dir=path.join(os.homedir(),'BackupsTrocaTicket/SupervisorCutover'),stateFile=path.join(dir,'estado.json'),stateBytes=fs.readFileSync(stateFile),e=JSON.parse(stateBytes),envFile=path.join(root,'.env'),envBytes=fs.readFileSync(envFile),env=require('dotenv').parse(envBytes);
 require('../preparacao-restabelecimento-pos-t1-20261103/candidato/scripts/preflight-reinicio-pos-t1.cjs').conferirOrigem(e,env);
 const x=e.transicao.t1,journalFile=path.join(dir,'t1-'+x.run+'.privado.json'),journal=fs.readFileSync(journalFile),record={...x};delete record.journalSha256;assert.equal(sha(journal),x.journalSha256);assert.deepEqual(JSON.parse(journal),record);
 const prior=JSON.parse(fs.readFileSync(path.join(__dirname,'janela-final-real-20261031.json'))),checkpointFile=path.join(prior.t0Directory,'checkpoint-t0.privado.json'),checkpoint=fs.readFileSync(checkpointFile),saved=JSON.parse(checkpoint);assert.equal(sha(checkpoint),e.transicao.recuperacao.decisaoSeguranca.checkpointSha256);assert.equal(saved.checkpointId,e.transicao.checkpointId);const backupsVerified=require('../scripts/backups-t0.cjs').validarArtefatosT0(saved.backups);
 assert.ok(['localhost','127.0.0.1','::1'].includes(env.DB_HOST));let c;try{c=await require('mysql2/promise').createConnection({host:env.DB_HOST,port:Number(env.DB_PORT||3306),user:env.DB_USER,password:env.DB_PASSWORD,database:env.DB_NAME,connectTimeout:7000});const query=sql=>c.query({sql,timeout:7000});await query('SET SESSION TRANSACTION READ ONLY');await query('START TRANSACTION READ ONLY');const [rows]=await query('SELECT 1 AS conectado, @@session.tx_read_only AS somente_leitura');assert.equal(Number(rows[0].conectado),1);assert.equal(Number(rows[0].somente_leitura),1);await c.rollback();}finally{if(c)await c.end();}
 assert.ok(fs.readFileSync(stateFile).equals(stateBytes));assert.ok(fs.readFileSync(envFile).equals(envBytes));assert.ok(fs.readFileSync(journalFile).equals(journal));assert.ok(fs.readFileSync(checkpointFile).equals(checkpoint));
 const file=path.join(__dirname,'precheck-admissao-pos-t1-'+Date.now()+'.json'),result={checkedUtc:new Date().toISOString(),status:'PRECHECK_APROVADO',mysqlReadOnlyVerified:true,t1ConcludedAndCleanupRecorded:true,t1JournalMatchesState:true,backupsVerified,protectedHashes:{state:sha(stateBytes),environmentJwt:sha(envBytes),checkpoint:sha(checkpoint),journal:sha(journal)},checkpointId:saved.checkpointId,journalRun:x.run,oldControllerPid:e.controleSelado.controlador.pid,oldSupervisorPid:e.controleSelado.supervisor.pid,admissionExecuted:false,dataWrites:false};fs.writeFileSync(file,JSON.stringify(result,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({ok:true,status:result.status,file:path.basename(file),mysqlReadOnlyVerified:true,t1JournalMatchesState:true,backupsVerified}));
}
main().catch(e=>{console.log(JSON.stringify({ok:false,code:/^[A-Z0-9_]+$/.test(e.code||'')?e.code:'PRECHECK_RECUSADO',admissionExecuted:false}));process.exitCode=1;});
